using UnityEngine;using UnityEditor;using System;using System.Linq;using System.Collections.Generic;
public static class RoomFixtureChecks {
 static void Emission(GameObject model,bool lit,string context){foreach(var r in model.GetComponentsInChildren<Renderer>(true)){if(r is ParticleSystemRenderer)continue;if(!r.sharedMaterials.Any(m=>m!=null&&m.HasProperty("_EmissionColor")&&m.IsKeywordEnabled("_EMISSION")))continue;var block=new MaterialPropertyBlock();r.GetPropertyBlock(block);var c=block.GetColor("_EmissionColor");if(lit?c.maxColorComponent<=.001f:c.maxColorComponent>.001f)throw new Exception("Emission state "+context+"/"+r.name+" "+c);}}
 public static string Run(){if(!Application.isPlaying)throw new Exception("Play Mode required");int rooms=0,fixtures=0,rituals=0,decorations=0;var holder=new GameObject("Fixture validation");try{var fuse=holder.AddComponent<FuseBox>();foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/Building"})){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(guid));if(prefab.GetComponent<Room>()==null)continue;var root=UnityEngine.Object.Instantiate(prefab,new Vector3(10000,0,10000),Quaternion.identity,holder.transform);try{rooms++;var room=root.GetComponent<Room>();var controls=room.GetLightObjects();var switches=root.GetComponentsInChildren<LightSwitchInteractable>(true);foreach(var on in new[]{false,true}){foreach(var s in switches)s.SwitchLight(on);foreach(var lo in controls){fixtures++;var so=new SerializedObject(lo);var group=so.FindProperty("lights").objectReferenceValue as GameObject;var model=so.FindProperty("model").objectReferenceValue as GameObject;if(group==null||model==null||lo.IsOn!=on||group.activeSelf!=on)throw new Exception("Control wiring "+root.name+"/"+lo.name);if(on&&!group.GetComponentsInChildren<Light>(true).Any(l=>l.enabled&&l.gameObject.activeInHierarchy&&l.intensity>0&&l.range>0))throw new Exception("Glowing fixture without light "+root.name+"/"+lo.name);Emission(model,on,root.name+"/"+lo.name);}}
 fuse.SetControlledRooms(new[]{room});fuse.ActivateFuseBox(false);foreach(var lo in controls){var so=new SerializedObject(lo);var group=(GameObject)so.FindProperty("lights").objectReferenceValue;var model=(GameObject)so.FindProperty("model").objectReferenceValue;if(group.activeSelf||lo.IsPowered)throw new Exception("Fuse wiring "+lo.name);Emission(model,false,root.name+" fuse off");}fuse.ActivateFuseBox(true);
 foreach(var candle in root.GetComponentsInChildren<RitualCandle>(true)){rituals++;candle.ExtinguishCandle();Emission(candle.gameObject,false,root.name+" candle off");candle.LightCandle();Emission(candle.gameObject,true,root.name+" candle on");if(!candle.GetComponentsInChildren<Light>(true).Any(l=>l.enabled&&l.gameObject.activeSelf&&l.intensity>0))throw new Exception("Candle glow without light "+root.name+"/"+candle.name);candle.ExtinguishCandle();}
 foreach(var r in root.GetComponentsInChildren<Renderer>(true)){if(r.sharedMaterials.Any(m=>m!=null&&m.name.Contains("_NoEmission"))){decorations++;if(r.sharedMaterials.Any(m=>m!=null&&m.IsKeywordEnabled("_EMISSION")&&m.GetColor("_EmissionColor").maxColorComponent>.001f))throw new Exception("Decorative glow "+r.name);}}
 if(root.name.StartsWith("J_DungeonRoom")&&root.GetComponentsInChildren<Light>(true).Any(l=>!l.enabled||!l.gameObject.activeInHierarchy))throw new Exception("Torch power regression");
 }finally{UnityEngine.Object.DestroyImmediate(root);}}return rooms+" room prefabs: "+fixtures/2+" fixtures pass switch on/off and fuse outage emission/light checks; "+rituals+" ritual candles pass; "+decorations+" decorative renderers non-emissive";}finally{UnityEngine.Object.DestroyImmediate(holder);}}
}

